import json
import itertools

def plan_trip():
    # Input variables
    total_days = 18
    cities = ["London", "Santorini", "Split"]
    required_stays = {"Split": 6, "Santorini": 7, "London": 7}
    conference_city = "Santorini"
    conference_days = [12, 18]
    direct_flights = {("London", "Santorini"), ("London", "Split")}  # undirected

    def is_direct(a, b):
        return (a, b) in direct_flights or (b, a) in direct_flights

    # Validate basic feasibility: sum of required stays must equal total days + number of flights (2 transitions)
    if sum(required_stays.values()) != total_days + 2:
        return {"error": "No feasible itinerary: stay totals inconsistent with required number of transitions."}

    solutions = []

    # Consider all paths of 3 cities with valid direct flights between consecutive cities
    for path in itertools.permutations(cities, 3):
        A, B, C = path
        if not (is_direct(A, B) and is_direct(B, C)):
            continue

        # Compute transition days d1 (A->B) and d2 (B->C) from required stays
        d1 = required_stays[A]  # Days 1..d1 include city A
        d2 = d1 + required_stays[B] - 1  # Days d1..d2 include city B
        # City C then occupies days d2..total_days (inclusive)

        # Check bounds and stays
        if not (1 <= d1 <= d2 <= total_days):
            continue
        c_days = total_days - d2 + 1
        if c_days != required_stays[C]:
            continue

        # Build day ranges per city
        ranges = {
            A: (1, d1),
            B: (d1, d2),
            C: (d2, total_days),
        }

        # Verify conference constraints: must be in conference_city on specified days
        def in_city_on_day(city, day):
            start, end = ranges[city]
            return start <= day <= end

        if any(not in_city_on_day(conference_city, d) for d in conference_days):
            continue

        # Additional verification: count days per city considering overlap on flight days
        city_counts = {city: 0 for city in cities}
        for day in range(1, total_days + 1):
            # Membership: A includes 1..d1; B includes d1..d2; C includes d2..total_days
            if in_city_on_day(A, day):
                city_counts[A] += 1
            if in_city_on_day(B, day):
                city_counts[B] += 1
            if in_city_on_day(C, day):
                city_counts[C] += 1

        if any(city_counts[city] != required_stays[city] for city in cities):
            continue

        # Store feasible solution
        itinerary = [
            {"day_range": f"Day {ranges[A][0]}-{ranges[A][1]}", "place": A},
            {"day_range": f"Day {ranges[B][0]}-{ranges[B][1]}", "place": B},
            {"day_range": f"Day {ranges[C][0]}-{ranges[C][1]}", "place": C},
        ]
        solutions.append(itinerary)

    if not solutions:
        return {"error": "No feasible itinerary found with given constraints."}

    # Choose the first feasible solution (all valid solutions are equivalent under given constraints)
    return {"itinerary": solutions[0]}

if __name__ == "__main__":
    result = plan_trip()
    print(json.dumps(result, ensure_ascii=False))
